CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260324162219_InitialCreate') THEN
    CREATE TABLE "SilverbackOutboxMessages" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "Content" bytea NOT NULL,
        "Headers" character varying(1000),
        "EndpointName" character varying(500) NOT NULL,
        "DynamicEndpoint" character varying(1000),
        "Created" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_SilverbackOutboxMessages" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260324162219_InitialCreate') THEN
    CREATE TABLE "UserProfiles" (
        "Id" uuid NOT NULL,
        "UserName" character varying(100) NOT NULL,
        "NormalizedUserName" character varying(100) NOT NULL,
        "DisplayName" character varying(120) NOT NULL,
        "AvatarUrl" character varying(500),
        "Bio" character varying(500),
        "IsActive" boolean NOT NULL,
        "LastSeenAtUtc" timestamp with time zone,
        "IsEmailVisible" boolean NOT NULL DEFAULT TRUE,
        "IsPhoneVisible" boolean NOT NULL DEFAULT TRUE,
        "CreatedBy" character varying(256) NOT NULL,
        "CreatedDate" timestamp with time zone NOT NULL,
        "LastModifiedBy" character varying(256) NOT NULL,
        "LastModifiedDate" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_UserProfiles" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260324162219_InitialCreate') THEN
    CREATE TABLE "Emails" (
        "Id" uuid NOT NULL,
        "UserProfileId" uuid NOT NULL,
        "Address" character varying(256) NOT NULL,
        "IsMain" boolean NOT NULL DEFAULT FALSE,
        "LastModifiedBy" text NOT NULL,
        "LastModifiedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Emails" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Emails_UserProfiles_UserProfileId" FOREIGN KEY ("UserProfileId") REFERENCES "UserProfiles" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

