        CONSTRAINT "PK_Phones" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Phones_UserProfiles_UserProfileId" FOREIGN KEY ("UserProfileId") REFERENCES "UserProfiles" ("Id") ON DELETE CASCADE
