DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260324180630_RenameAuditTimestampColumns') THEN
    UPDATE "UserProfiles"
    SET "CreatedAtUtc" = CURRENT_TIMESTAMP,
        "LastModifiedAtUtc" = CURRENT_TIMESTAMP
    WHERE "CreatedAtUtc" IS NULL
       OR "LastModifiedAtUtc" IS NULL;
