END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260329111500_AddEmailIsAuth') THEN
    DROP INDEX uq_email_user_profile_address;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260329111500_AddEmailIsAuth') THEN
    UPDATE "Emails" AS e
    SET "IsAuth" = TRUE
    FROM (
        SELECT DISTINCT ON ("UserProfileId") "Id"
        FROM "Emails"
        ORDER BY "UserProfileId", "IsMain" DESC, "CreatedAtUtc", "Id"
    ) AS selected
    WHERE e."Id" = selected."Id";
    END IF;
END $EF$;

